const d = $('Donnees dashboard').first().json || {};
const net = (v) => String(v ?? '').replace(/[*_`\[\]]/g, '').trim();
const fcfa = (n) => Number(n || 0).toLocaleString('fr-FR');

const jour = d.jour || [];
const semaine = d.semaine || [];

let m = `📊 *ETAT DU JOUR*\n`;
if (jour.length) {
  for (const b of jour) {
    m += `\n🏪 *${net(b.boutique_nom)}*\n`;
    m += `▸ Commandes : *${b.commandes}* · livrees : *${b.livrees}*\n`;
    m += `▸ CA : *${fcfa(b.ca)} FCFA* · panier : *${fcfa(b.panier_moyen)} FCFA*\n`;
  }
} else {
  m += `\nAucune commande aujourd hui.\n`;
}

m += `\n━━━━━━━━━━━━━━━━\n📅 *7 DERNIERS JOURS*\n`;
if (semaine.length) {
  for (const b of semaine) {
    m += `\n🏪 *${net(b.boutique_nom)}* : *${b.commandes}* commandes · *${fcfa(b.ca)} FCFA*\n`;
  }
} else {
  m += `\nAucune commande cette semaine.\n`;
}

return [{ json: { message: m } }];

const d = $('Donnees dashboard').first().json || {};
const net = (v) => String(v ?? '').replace(/[*_`\[\]]/g, '').trim();

const plats = d.plats_tout || [];
if (!plats.length) return [{ json: { message: '🍽️ Aucune vente enregistree.' } }];

const par = new Map();
for (const p of plats) {
  const cle = p.boutique_nom || 'Boutique inconnue';
  if (!par.has(cle)) par.set(cle, []);
  par.get(cle).push(p);
}

let m = `🍽️ *MEILLEURES VENTES*\n`;
for (const [boutique, liste] of par) {
  m += `\n━━━━━━━━━━━━━━━━\n🏪 *${net(boutique)}*\n`;
  liste.slice(0, 5).forEach((p, i) => {
    m += `${i + 1}. ${net(p.produit)} : *${p.quantite}* vendu(s)\n`;
  });
}
return [{ json: { message: m } }];

const d = $('Donnees dashboard').first().json || {};
const net = (v) => String(v ?? '').replace(/[*_`\[\]]/g, '').trim();

const retards = d.retards || [];
if (!retards.length) return [{ json: { message: '✅ Aucune commande en retard.' } }];

const par = new Map();
for (const r of retards) {
  const cle = r.boutique_nom || 'Boutique inconnue';
  if (!par.has(cle)) par.set(cle, []);
  par.get(cle).push(r);
}

let m = `⚠️ *COMMANDES EN RETARD*\n`;
for (const [boutique, liste] of par) {
  m += `\n━━━━━━━━━━━━━━━━\n🏪 *${net(boutique)}* — ${liste.length} commande(s)\n`;
  for (const r of liste) {
    m += `\n• ${net(r.order_id)} — *${r.minutes} min*\n`;
    m += `  👤 ${net(r.client_nom)} · 📞 ${net(r.client_telephone)}\n`;
    m += `  📍 ${net(r.client_adresse)}\n`;
    m += `  🛵 ${net(r.nom_livreur) || 'Non assigne'}\n`;
  }
}
return [{ json: { message: m } }];

