const d = $('Donnees dashboard').first().json || {};
const net = (v) => String(v ?? '').replace(/[*_`\[\]]/g, '').trim();
const fcfa = (n) => Number(n || 0).toLocaleString('fr-FR');

const bloc = (liste) => (liste && liste.length)
  ? liste.map((b) => `🏪 *${net(b.boutique_nom)}* : *${fcfa(b.ca)} FCFA* (${b.commandes} cmd)`).join('\n')
  : '—';

let m = `💰 *CHIFFRE D AFFAIRES*\n`;
m += `\n📅 *Aujourd hui*\n${bloc(d.jour)}\n`;
m += `\n📅 *7 derniers jours*\n${bloc(d.semaine)}\n`;
m += `\n📅 *Depuis l origine*\n${bloc(d.tout)}\n`;

return [{ json: { message: m } }];

// Le gerant a tape autre chose qu'une commande connue : on lui rappelle
// lesquelles existent plutot que de rester muet.
const m = [
  '🤖 *Commandes disponibles*',
  '',
  '/stats — activite du jour et de la semaine',
  '/ca — chiffre d affaires sur trois periodes',
  '/top — meilleures ventes',
  '/clients — meilleurs clients',
  '/retard — commandes en souffrance',
  '/stock — produits sous seuil',
  '/total — cumul depuis l origine',
].join('\n');

return [{ json: { message: m } }];

const d = $('Donnees dashboard').first().json || {};
const net = (v) => String(v ?? '').replace(/[*_`\[\]]/g, '').trim();

const stocks = d.stocks || [];
if (!stocks.length) return [{ json: { message: '✅ Aucun produit sous seuil.' } }];

const par = new Map();
for (const s of stocks) {
  const cle = s.boutique_nom || 'Boutique inconnue';
  if (!par.has(cle)) par.set(cle, []);
  par.get(cle).push(s);
}

let m = `🚨 *STOCKS SOUS SEUIL*\n`;
for (const [boutique, liste] of par) {
  m += `\n━━━━━━━━━━━━━━━━\n🏪 *${net(boutique)}*\n`;
  for (const s of liste) {
    m += s.niveau === 'critique'
      ? `🔴 *${net(s.produit)}* : ${s.restant} restant(s) (seuil ${s.seuil})\n`
      : `🟠 *${net(s.produit)}* : ${s.restant} restant(s) (seuil ${s.seuil})\n`;
  }
}
return [{ json: { message: m } }];

const d = $('Donnees dashboard').first().json || {};
const net = (v) => String(v ?? '').replace(/[*_`\[\]]/g, '').trim();
const fcfa = (n) => Number(n || 0).toLocaleString('fr-FR');

const tout = d.tout || [];
if (!tout.length) return [{ json: { message: '📈 Aucune commande enregistree.' } }];

let m = `📈 *CUMUL DEPUIS L ORIGINE*\n`;
let caTotal = 0;
let cmdTotal = 0;

for (const b of tout) {
  caTotal += Number(b.ca || 0);
  cmdTotal += Number(b.commandes || 0);
  m += `\n━━━━━━━━━━━━━━━━\n🏪 *${net(b.boutique_nom)}*\n`;
  m += `▸ Commandes : *${b.commandes}* · livrees : *${b.livrees}* · annulees : *${b.annulees}*\n`;
  m += `▸ CA : *${fcfa(b.ca)} FCFA* · panier : *${fcfa(b.panier_moyen)} FCFA*\n`;
  if (b.avis > 0) m += `▸ Satisfaction : *${String(b.note_moyenne).replace('.', ',')}/5* (${b.avis} avis)\n`;
}

if (tout.length > 1) {
  m += `\n━━━━━━━━━━━━━━━━\n🌐 *TOUTES BOUTIQUES*\n`;
  m += `▸ Commandes : *${cmdTotal}* · CA : *${fcfa(caTotal)} FCFA*\n`;
}

return [{ json: { message: m } }];

// Les huit commandes composent un seul message, balise a l'asterisque. Or les
// deux canaux ne lisent pas le meme balisage : WhatsApp met en gras entre
// asterisques nativement, Telegram non — il faut lui envoyer du HTML et le
// lui dire. Sans cette traduction, le gerant lisait ses asterisques en clair
// a chaque commande, sur Telegram uniquement.
const brut = String($input.first().json.message || '');

// On echappe AVANT de baliser : l'inverse transformerait nos propres balises
// en entites. Une esperluette dans un nom de produit fait echouer l'envoi
// entier cote Telegram, et le gerant ne recoit alors rien du tout.
const echappe = brut
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

// Paires d'asterisques sur une meme ligne. Un asterisque isole reste litteral
// plutot que d'ouvrir une balise qui ne se refermerait jamais.
const message_telegram = echappe.replace(/\*([^*\n]+)\*/g, '<b>$1</b>');

return [{ json: { message_telegram, message_whatsapp: brut } }];
